// Package praxisprov serves where each Praxis template setting came from: the
// book or course and passage in the operator's library, or, where the library
// gives no value, which Microsoft source supplied it. Generated by
// scripts/build_praxis.py alongside the templates themselves.
package praxisprov

import (
	_ "embed"
	"encoding/json"
)

//go:embed provenance.json
var raw []byte

type Citation struct {
	Course  string `json:"course"`
	Passage int    `json:"passage"`
	Key     string `json:"key"`
}

type Setting struct {
	Setting   string     `json:"setting"`
	Value     string     `json:"value"`
	Source    string     `json:"source"` // library | microsoft | judgement
	Citations []Citation `json:"citations"`
	Note      string     `json:"note,omitempty"`
}

type Template struct {
	Why      string    `json:"why,omitempty"`
	Requires string    `json:"requires,omitempty"`
	Settings []Setting `json:"settings"`
}

type Provenance struct {
	Templates map[string]Template `json:"templates"` // keyed by policy display name
}

func Load() (*Provenance, error) {
	var p Provenance
	return &p, json.Unmarshal(raw, &p)
}
